window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-a7e435a14b24eeaf"]={"versions": [{"id": "FIG-a7e435a14b24eeaf", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Sequenzdiagramm (Interaktionsdiagramm zur Darstellung eines Fehlerszenarios).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Adaptive Platform (AP), Release R24-11, Dokument <em>AUTOSAR_AP_EXP_SWArchitecture</em>.</li>\n<li><strong>Funktionaler Zweck:</strong> Visualisierung des Fehlerbehandlungs- und Eskalationspfades bei fehlgeschlagener Überwachung (<em>Supervision Failure</em>). Dargestellt ist das Fallback-Szenario, in dem das <em>State Management</em> (SM) eine vom <em>Platform Health Management</em> (PHM) angeforderte Wiederherstellungsaktion nicht ausführen kann (<code>kSMCanNotHandleRecovery</code>) und PHM die letzte funktionale Sicherheitsebene durch Auslösen eines Watchdog-Resets über das <code>WatchdogInterface</code> erzwingt.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Akteure / Lebenslinien:</strong></li>\n<li><code>«aapFunctionalCluster» :Platform Health Management</code>: Zentraler Functional Cluster zur Laufzeitüberwachung (Alive-, Deadline- und Logical Supervision sowie Health Channel Monitoring) von Adaptive Applications und Plattform-Prozessen.</li>\n<li><code>«aapFunctionalCluster» :State Management</code>: Zentraler Functional Cluster für Zustandsübergänge (Function Groups, Machine States) und koordinierte Recovery-Aktionen auf Applikations- und Maschinenebene.</li>\n<li><code>:WatchdogInterface</code>: Plattformnahe Abstraktions-/Treiberschnittstelle zur Hardware-Watchdog-Ansteuerung bzw. Watchdog-Daemon-Interaktion.</li>\n<li><strong>Stereotypen:</strong></li>\n<li><code>«aapFunctionalCluster»</code>: Kennzeichnet standardisierte Systemdienste der AUTOSAR Adaptive Platform-Architektur.</li>\n<li><code>«aapInformative»</code>: Markiert architekturell informative Interaktionen bzw. interne Pseudomethoden, die keine normative 1:1-C++-API-Signatur der AUTOSAR-SWS darstellen.</li>\n<li><strong>Schnittstellen & Interaktionsbeziehungen:</strong></li>\n<li>Interaktion zwischen SM und PHM über ARA-Dienste (Service-Oriented Communication via <code>ara::com</code> oder direkte IPC-Bindings).</li>\n<li>Direkte Schnittstelle von PHM zu Hardware-/OS-Ebene über das <code>WatchdogInterface</code>.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Initialisierung / Service Binding:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>:State Management</code> sendet <code>Offer()</code> an <code>:Platform Health Management</code>, um seine Schnittstelle/Bereitschaft für Recovery-Handler bereitzustellen (Service Discovery / Initialisierung).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Fehler-Trigger:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Eingehender Trigger <code>supervisionFailed() «aapInformative»</code> (ausgelöst durch Checkpoint-Verletzung, Timeout der Alive-Supervision, fehlerhafte Ausführungsreihenfolge oder externe Systemfehler).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Interne Auswertung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>PHM führt intern <code>handleFailedSupervision() «aapInformative»</code> aus, bewertet den Systemzustand und ermittelt die konfigurierte Recovery-Aktion.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Delegation an State Management:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Synchroner Methodenaufruf <code>RecoveryHandler()</code> von PHM an SM zur Einleitung einer softwareseitigen Fehlerbehebung (z. B. Prozessneustart, Zustandswechsel in einen Safe State oder degraded Mode).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Fehlgeschlagene Recovery (Negativer Rückgabewert):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>SM antwortet mit dem Return-Code / Fehlerstatus <code>:kSMCanNotHandleRecovery</code>. SM signalisiert damit, dass die angeforderte Recovery-Strategie nicht anwendbar, blockiert oder fehlgeschlagen ist.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Eskalation / Watchdog-Reaktion:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>PHM aktiviert den konfigurierten Eskalationspfad und ruft synchron/direkt <code>FireWatchdogReaction()</code> auf dem <code>:WatchdogInterface</code> auf. Dies führt zum Stoppen des Watchdog-Triggerns bzw. zur unmittelbaren Hard-/Firmware-Reset-Auslösung der Maschine.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Konfigurationsaspekte (ARXML / Manifest):</strong></li>\n<li>Im Execution- und Health-Management-Manifest müssen für die jeweiligen Supervisions explizite <em>Recovery Actions</em> definiert werden.</li>\n<li>Das Eskalationsverhalten bei fehlschlagendem SM-Recovery-Handling muss deterministisch auf Hardware- bzw. Plattform-Watchdog-Aktionen abgebildet sein (<code>WatchdogAction</code> / <code>PlatformHealthManagementAction</code>).</li>\n<li><strong>API-Vertrag & Fehlertoleranzzeit (FHTT / FTTI):</strong></li>\n<li><code>RecoveryHandler()</code> muss innerhalb der harten Echtzeitgrenzen der ASIL-Einstufung antworten. Bei blockierendem SM oder Rückgabe von <code>kSMCanNotHandleRecovery</code> greift die minimale verbleibende Fehlerreaktionszeit bis zum Watchdog-Ablauf.</li>\n<li>Entwickler von State-Management-Regeln müssen sicherstellen, dass <code>kSMCanNotHandleRecovery</code> nur als letzte Instanz gemeldet wird, da die Konsequenz der vollständige Neustart der Partition/ECU ist.</li>\n<li><strong>Plattform- und Treiberintegration:</strong></li>\n<li>Das <code>WatchdogInterface</code> muss vom BSP-/OS-Integrator so implementiert sein, dass <code>FireWatchdogReaction()</code> entweder unmittelbar den Refresh-Zyklus beendet oder einen kontrollierten Reset über das WDG-Peripheral/SBC forciert.</li>\n</ul>"}, {"id": "FIG-58bf7625dd1f86c2", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Sequenzdiagramm (Interaktionsdiagramm zur Darstellung eines Fehlerszenarios).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Adaptive Platform (AP), Release R24-11, Dokument <em>AUTOSAR_AP_EXP_SWArchitecture</em>.</li>\n<li><strong>Funktionaler Zweck:</strong> Visualisierung des Fehlerbehandlungs- und Eskalationspfades bei fehlgeschlagener Überwachung (<em>Supervision Failure</em>). Dargestellt ist das Fallback-Szenario, in dem das <em>State Management</em> (SM) eine vom <em>Platform Health Management</em> (PHM) angeforderte Wiederherstellungsaktion nicht ausführen kann (<code>kSMCanNotHandleRecovery</code>) und PHM die letzte funktionale Sicherheitsebene durch Auslösen eines Watchdog-Resets über das <code>WatchdogInterface</code> erzwingt.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Akteure / Lebenslinien:</strong></li>\n<li><code>«aapFunctionalCluster» :Platform Health Management</code>: Zentraler Functional Cluster zur Laufzeitüberwachung (Alive-, Deadline- und Logical Supervision sowie Health Channel Monitoring) von Adaptive Applications und Plattform-Prozessen.</li>\n<li><code>«aapFunctionalCluster» :State Management</code>: Zentraler Functional Cluster für Zustandsübergänge (Function Groups, Machine States) und koordinierte Recovery-Aktionen auf Applikations- und Maschinenebene.</li>\n<li><code>:WatchdogInterface</code>: Plattformnahe Abstraktions-/Treiberschnittstelle zur Hardware-Watchdog-Ansteuerung bzw. Watchdog-Daemon-Interaktion.</li>\n<li><strong>Stereotypen:</strong></li>\n<li><code>«aapFunctionalCluster»</code>: Kennzeichnet standardisierte Systemdienste der AUTOSAR Adaptive Platform-Architektur.</li>\n<li><code>«aapInformative»</code>: Markiert architekturell informative Interaktionen bzw. interne Pseudomethoden, die keine normative 1:1-C++-API-Signatur der AUTOSAR-SWS darstellen.</li>\n<li><strong>Schnittstellen & Interaktionsbeziehungen:</strong></li>\n<li>Interaktion zwischen SM und PHM über ARA-Dienste (Service-Oriented Communication via <code>ara::com</code> oder direkte IPC-Bindings).</li>\n<li>Direkte Schnittstelle von PHM zu Hardware-/OS-Ebene über das <code>WatchdogInterface</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Initialisierung / Service Binding:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>:State Management</code> sendet <code>Offer()</code> an <code>:Platform Health Management</code>, um seine Schnittstelle/Bereitschaft für Recovery-Handler bereitzustellen (Service Discovery / Initialisierung).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Fehler-Trigger:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Eingehender Trigger <code>supervisionFailed() «aapInformative»</code> (ausgelöst durch Checkpoint-Verletzung, Timeout der Alive-Supervision, fehlerhafte Ausführungsreihenfolge oder externe Systemfehler).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Interne Auswertung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>PHM führt intern <code>handleFailedSupervision() «aapInformative»</code> aus, bewertet den Systemzustand und ermittelt die konfigurierte Recovery-Aktion.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Delegation an State Management:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Synchroner Methodenaufruf <code>RecoveryHandler()</code> von PHM an SM zur Einleitung einer softwareseitigen Fehlerbehebung (z. B. Prozessneustart, Zustandswechsel in einen Safe State oder degraded Mode).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Fehlgeschlagene Recovery (Negativer Rückgabewert):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>SM antwortet mit dem Return-Code / Fehlerstatus <code>:kSMCanNotHandleRecovery</code>. SM signalisiert damit, dass die angeforderte Recovery-Strategie nicht anwendbar, blockiert oder fehlgeschlagen ist.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Eskalation / Watchdog-Reaktion:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>PHM aktiviert den konfigurierten Eskalationspfad und ruft synchron/direkt <code>FireWatchdogReaction()</code> auf dem <code>:WatchdogInterface</code> auf. Dies führt zum Stoppen des Watchdog-Triggerns bzw. zur unmittelbaren Hard-/Firmware-Reset-Auslösung der Maschine.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Konfigurationsaspekte (ARXML / Manifest):</strong></li>\n<li>Im Execution- und Health-Management-Manifest müssen für die jeweiligen Supervisions explizite <em>Recovery Actions</em> definiert werden.</li>\n<li>Das Eskalationsverhalten bei fehlschlagendem SM-Recovery-Handling muss deterministisch auf Hardware- bzw. Plattform-Watchdog-Aktionen abgebildet sein (<code>WatchdogAction</code> / <code>PlatformHealthManagementAction</code>).</li>\n<li><strong>API-Vertrag & Fehlertoleranzzeit (FHTT / FTTI):</strong></li>\n<li><code>RecoveryHandler()</code> muss innerhalb der harten Echtzeitgrenzen der ASIL-Einstufung antworten. Bei blockierendem SM oder Rückgabe von <code>kSMCanNotHandleRecovery</code> greift die minimale verbleibende Fehlerreaktionszeit bis zum Watchdog-Ablauf.</li>\n<li>Entwickler von State-Management-Regeln müssen sicherstellen, dass <code>kSMCanNotHandleRecovery</code> nur als letzte Instanz gemeldet wird, da die Konsequenz der vollständige Neustart der Partition/ECU ist.</li>\n<li><strong>Plattform- und Treiberintegration:</strong></li>\n<li>Das <code>WatchdogInterface</code> muss vom BSP-/OS-Integrator so implementiert sein, dass <code>FireWatchdogReaction()</code> entweder unmittelbar den Refresh-Zyklus beendet oder einen kontrollierten Reset über das WDG-Peripheral/SBC forciert.</li>\n</ul>"}], "trans": [{"from": "FIG-a7e435a14b24eeaf", "to": "FIG-58bf7625dd1f86c2", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
